class FilterInValuesUndefTest {

	private static final ValueFactory VALUE_FACTORY = SimpleValueFactory.getInstance();

	@Test
	void undefValuesAnchorIsNotDroppedWhenJoinAssuresTheVariable() throws Exception {
		IRI predicate = VALUE_FACTORY.createIRI("urn:test:p");
		IRI expectedObject = VALUE_FACTORY.createIRI("urn:test:expected");
		Statement statement = VALUE_FACTORY.createStatement(VALUE_FACTORY.createIRI("urn:test:subject"), predicate,
				expectedObject);

		BindingSet undefRow = new ListBindingSet(List.of("x"), (Value) null);
		BindingSetAssignment existingValues = new BindingSetAssignment();
		existingValues.setBindingNames(Set.of("x"));
		existingValues.setBindingSets(List.of(undefRow));

		StatementPattern pattern = new StatementPattern(Var.of("subject"), Var.of("predicate", predicate), Var.of("x"));
		Filter filter = new Filter(new Join(existingValues, pattern),
				new SameTerm(Var.of("x"), new ValueConstant(expectedObject)));
		QueryRoot root = new QueryRoot(filter);
		new FilterInValuesOptimizer().optimize(root, (Dataset) null, EmptyBindingSet.getInstance());

		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new SingleStatementSource(statement), null);
		List<BindingSet> rows;
		try (CloseableIteration<BindingSet> iteration = strategy.precompile(root)
				.evaluate(EmptyBindingSet.getInstance())) {
			rows = Iterations.asList(iteration);
		}

		assertEquals(1, rows.size(), "an UNDEF VALUES row remains compatible with the assuring pattern");
		assertEquals(expectedObject, rows.get(0).getValue("x"));
	}

	@Test
	void undefValuesKeepTheFiniteFilterConstraintAndDuplicateMultiplicity() throws Exception {
		IRI predicate = VALUE_FACTORY.createIRI("urn:test:p");
		IRI expectedObject = VALUE_FACTORY.createIRI("urn:test:expected");
		IRI otherAllowedObject = VALUE_FACTORY.createIRI("urn:test:other-allowed");
		IRI disallowedObject = VALUE_FACTORY.createIRI("urn:test:disallowed");
		List<Statement> statements = List.of(
				VALUE_FACTORY.createStatement(VALUE_FACTORY.createIRI("urn:test:subject-1"), predicate, expectedObject),
				VALUE_FACTORY.createStatement(VALUE_FACTORY.createIRI("urn:test:subject-2"), predicate,
						otherAllowedObject),
				VALUE_FACTORY.createStatement(VALUE_FACTORY.createIRI("urn:test:subject-3"), predicate,
						disallowedObject));

		BindingSet firstUndefRow = new ListBindingSet(List.of("x"), (Value) null);
		BindingSet duplicateUndefRow = new ListBindingSet(List.of("x"), (Value) null);
		BindingSetAssignment existingValues = new BindingSetAssignment();
		existingValues.setBindingNames(Set.of("x"));
		existingValues.setBindingSets(List.of(firstUndefRow, duplicateUndefRow));

		StatementPattern pattern = new StatementPattern(Var.of("subject"), Var.of("predicate", predicate), Var.of("x"));
		ListMemberOperator condition = new ListMemberOperator();
		condition.addArgument(Var.of("x"));
		condition.addArgument(new ValueConstant(expectedObject));
		condition.addArgument(new ValueConstant(otherAllowedObject));
		Filter filter = new Filter(new Join(existingValues, pattern), condition);
		QueryRoot root = new QueryRoot(filter);
		new FilterInValuesOptimizer().optimize(root, (Dataset) null, EmptyBindingSet.getInstance());

		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new StatementListSource(statements), null);
		List<BindingSet> rows;
		try (CloseableIteration<BindingSet> iteration = strategy.precompile(root)
				.evaluate(EmptyBindingSet.getInstance())) {
			rows = Iterations.asList(iteration);
		}

		assertEquals(4, rows.size(), "both duplicate UNDEF rows must match the two allowed pattern values");
		assertEquals(2, rows.stream().filter(row -> expectedObject.equals(row.getValue("x"))).count());
		assertEquals(2, rows.stream().filter(row -> otherAllowedObject.equals(row.getValue("x"))).count());
		assertEquals(0, rows.stream().filter(row -> disallowedObject.equals(row.getValue("x"))).count(),
				"removing the filter must not admit pattern values outside the finite list");
	}

	private static final class SingleStatementSource implements TripleSource {
		private final Statement statement;

		private SingleStatementSource(Statement statement) {
			this.statement = statement;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			if ((subj == null || subj.equals(statement.getSubject()))
					&& (pred == null || pred.equals(statement.getPredicate()))
					&& (obj == null || obj.equals(statement.getObject()))) {
				return new CloseableIteratorIteration<>(List.of(statement).iterator());
			}
			return TripleSource.EMPTY_ITERATION;
		}

		@Override
		public ValueFactory getValueFactory() {
			return VALUE_FACTORY;
		}
	}

	private static final class StatementListSource implements TripleSource {
		private final List<Statement> statements;

		private StatementListSource(List<Statement> statements) {
			this.statements = statements;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			List<Statement> matches = statements.stream()
					.filter(statement -> (subj == null || subj.equals(statement.getSubject()))
							&& (pred == null || pred.equals(statement.getPredicate()))
							&& (obj == null || obj.equals(statement.getObject())))
					.toList();
			return new CloseableIteratorIteration<>(matches.iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return VALUE_FACTORY;
		}
	}
}
